import{_ as r,o as a,c as t,aF as s}from"./chunks/framework.CNkxH4QO.js";const o="/krawler-ekosystem/assets/krawler-overview.B7S1TVUf.png",p=JSON.parse('{"title":"Understanding Krawler","description":"Main concepts and architecture","frontmatter":{"title":"Understanding Krawler","description":"Main concepts and architecture"},"headers":[],"relativePath":"packages/krawler/guides/understanding.md","filePath":"packages/krawler/guides/understanding.md"}'),n={name:"packages/krawler/guides/understanding.md"};function i(l,e,h,d,c,g){return a(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="understanding-krawler" tabindex="-1">Understanding Krawler <a class="header-anchor" href="#understanding-krawler" aria-label="Permalink to &quot;Understanding Krawler&quot;">​</a></h1><p><strong>Krawler</strong> is powered by <a href="https://feathersjs.com/" target="_blank" rel="noreferrer">Feathers</a> and relies on two of its main abstractions: <a href="https://docs.feathersjs.com/api/services.html" target="_blank" rel="noreferrer">services</a> and <a href="https://docs.feathersjs.com/api/hooks.html" target="_blank" rel="noreferrer">hooks</a>. We assume you are familiar with this technology.</p><h2 id="main-concepts" tabindex="-1">Main concepts <a class="header-anchor" href="#main-concepts" aria-label="Permalink to &quot;Main concepts&quot;">​</a></h2><p><strong>Krawler</strong> manipulates three kinds of entities:</p><ul><li>a <strong>store</strong> defines where the extracted/processed data will reside,</li><li>a <strong>task</strong> defines what data is to be extracted and how to query it,</li><li>a <strong>job</strong> defines what tasks are to be run to fulfill a request (i.e. sequencing).</li></ul><p>On top of this, <a href="https://docs.feathersjs.com/api/hooks.html" target="_blank" rel="noreferrer">hooks</a> provide a set of functions that can typically be run before/after a task/job, such as a conversion after a download or task generation before a job run. More or less, this allows you to create a <a href="https://en.wikipedia.org/wiki/Pipeline_(computing)" target="_blank" rel="noreferrer">processing pipeline</a>.</p><p>Regarding store management we rely on <a href="https://github.com/maxogden/abstract-blob-store" target="_blank" rel="noreferrer">abstract-blob-store</a>, which abstracts a lot of different storage backends (local file system, AWS S3, in-memory, etc.), and is already used by <a href="https://github.com/feathersjs-ecosystem/feathers-blob" target="_blank" rel="noreferrer">feathers-blob</a>.</p><h2 id="global-overview" tabindex="-1">Global overview <a class="header-anchor" href="#global-overview" aria-label="Permalink to &quot;Global overview&quot;">​</a></h2><p>The following figure depicts the global architecture and all concepts at play:</p><p><img src="'+o+'" alt="Architecture"></p><h2 id="what-is-inside" tabindex="-1">What is inside? <a class="header-anchor" href="#what-is-inside" aria-label="Permalink to &quot;What is inside?&quot;">​</a></h2><p><strong>Krawler</strong> is made possible and mainly powered by the following stack:</p><ul><li><a href="https://feathersjs.com/" target="_blank" rel="noreferrer">Feathers</a> — the underlying services and hooks framework</li><li><a href="https://lodash.com/" target="_blank" rel="noreferrer">Lodash</a> — a JavaScript utility library, also used for <a href="https://lodash.com/docs/4.17.4#template" target="_blank" rel="noreferrer">templating</a></li><li><a href="https://github.com/mmomtchev/node-gdal-async" target="_blank" rel="noreferrer">gdal-async</a> — the Node.js bindings of <a href="https://gdal.org/" target="_blank" rel="noreferrer">GDAL / OGR</a> used to process rasters and vectors</li><li><a href="https://github.com/nodeca/js-yaml" target="_blank" rel="noreferrer">js-yaml</a> — used to process YAML files</li><li><a href="https://github.com/Leonidas-from-XIV/node-xml2js" target="_blank" rel="noreferrer">xml2js</a> — used to process XML files</li><li><a href="https://www.papaparse.com/" target="_blank" rel="noreferrer">Papa Parse</a> — used to read and write CSV files</li><li><a href="https://github.com/maxogden/abstract-blob-store" target="_blank" rel="noreferrer">abstract-blob-store</a> — used to abstract storage</li><li><a href="https://github.com/sindresorhus/got" target="_blank" rel="noreferrer">got</a> — used to manage HTTP requests</li><li><a href="https://github.com/brianc/node-postgres" target="_blank" rel="noreferrer">node-postgres</a> — used to manage PostgreSQL databases</li><li><a href="https://github.com/mongodb/node-mongodb-native" target="_blank" rel="noreferrer">node-mongodb-native</a> — used to manage MongoDB databases</li></ul><p>Krawler ships as a native <a href="https://nodejs.org/api/esm.html" target="_blank" rel="noreferrer">ES module</a> (<code>&quot;type&quot;: &quot;module&quot;</code>) and targets <strong>Node.js &gt;= 20</strong>.</p><h2 id="going-further" tabindex="-1">Going further <a class="header-anchor" href="#going-further" aria-label="Permalink to &quot;Going further&quot;">​</a></h2><p>Once the concepts are clear, head to the API reference to learn how each entity is configured:</p><ul><li>the <a href="./../reference/services.html">services reference</a> details stores, tasks and jobs,</li><li>the <a href="./../reference/hooks.html">hooks reference</a> details all the built-in processing functions,</li><li>the <a href="./../reference/known-issues.html">known issues</a> cover advanced pipeline patterns (reusing hooks, parallelism, error handling).</li></ul>',17)])])}const u=r(n,[["render",i]]);export{p as __pageData,u as default};
